{"title": "死循环画布", "note": "画布里转死循环", "html": "<style>
  .line{font-size:var(--font-text-sm-size);color:var(--color-text-secondary)}
</style>
<div class="line" id="spin">画布里的脚本转起来了</div>
<script>
  setTimeout(function () {
    var i = 0;
    while (true) { i += 1; }
  }, 80);
</script>"}

